import { useEffect, useId, useRef, useState } from 'react';
import './CommandPalette.css';
// No package API or documentation was supplied with this request. This
// application-local composition therefore makes no claim to use package exports.
// The application supplies command policy, matching, execution and recent IDs.
export interface Command { id: string; title: string; group: string }
export function CommandPalette({ open, commands, recentIds, onClose, onExecute, onRemember, matches }: {
  open: boolean; commands: readonly Command[]; recentIds: readonly string[];
  onClose: () => void; onExecute: (id: string) => void; onRemember: (id: string) => void;
  matches: (command: Command, query: string) => boolean;
}) {
  const dialog = useRef<HTMLDialogElement>(null);
  const search = useRef<HTMLInputElement>(null);
  const id = useId();
  const [query, setQuery] = useState('');
  const [active, setActive] = useState(0);
  const recent = [...new Set(recentIds)].flatMap(commandId => { const command = commands.find(item => item.id === commandId); return command ? [command] : []; });
  const groups = new Map<string, Command[]>();
  if (!query.trim() && recent.length) groups.set('Recent commands', recent);
  for (const command of commands) {
    if (!matches(command, query) || (!query.trim() && recent.some(item => item.id === command.id))) continue;
    const group = groups.get(command.group) ?? [];
    group.push(command); groups.set(command.group, group);
  }
  const results = [...groups.values()].flat();
  const selected = Math.min(active, Math.max(0, results.length - 1));
  useEffect(() => {
    if (!open) return;
    const previous = document.activeElement as HTMLElement | null;
    setQuery(''); setActive(0);
    dialog.current?.showModal(); search.current?.focus();
    return () => { dialog.current?.close(); previous?.focus(); };
  }, [open]);
  function execute(command: Command) { onExecute(command.id); onRemember(command.id); onClose(); }
  return <dialog ref={dialog} className="command-palette" aria-labelledby={id + '-title'} onCancel={event => { event.preventDefault(); onClose(); }}>
    <h2 id={id + '-title'}>Commands</h2>
    <label htmlFor={id + '-input'}>Search commands</label>
    <input id={id + '-input'} ref={search} role="combobox" aria-autocomplete="list" aria-expanded={true} aria-controls={id + '-results'} aria-activedescendant={results.length ? id + '-option-' + selected : undefined} value={query} onChange={event => { setQuery(event.target.value); setActive(0); }}
      onKeyDown={event => {
        if (event.nativeEvent.isComposing) return;
        if (results.length && ['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) {
          event.preventDefault();
          setActive(event.key === 'Home' ? 0 : event.key === 'End' ? results.length - 1 : (selected + (event.key === 'ArrowDown' ? 1 : -1) + results.length) % results.length);
        } else if (event.key === 'Enter' && results[selected]) { event.preventDefault(); execute(results[selected]); }
      }}/>
    <p role="status">{results.length ? results.length + ' commands available' : 'No commands found. Try another search.'}</p>
    <div id={id + '-results'} role="listbox" aria-label="Commands">{[...groups].map(([group, items], groupIndex) => <div key={group} role="group" aria-labelledby={id + '-group-' + groupIndex}><h3 id={id + '-group-' + groupIndex}>{group}</h3>{items.map(command => { const index = results.indexOf(command); return <div key={command.id} role="option" id={id + '-option-' + index} aria-selected={selected === index} onMouseDown={event => event.preventDefault()} onClick={() => execute(command)}>{command.title}</div>; })}</div>)}</div>
    <button type="button" onClick={onClose}>Close</button>
  </dialog>;
}

