.command-palette { box-sizing: border-box; width: min(36rem, calc(100vw - 2rem)); max-height: calc(100dvh - 2rem); overflow: auto; margin: auto; padding: 1.25rem; border: 1px solid #919baa; border-radius: .5rem; color: #20232a; background: white; }
.command-palette::backdrop { background: rgb(0 0 0 / .45); }
.command-palette input { display: block; width: 100%; box-sizing: border-box; padding: .6rem; margin-top: .4rem; font: inherit; }
.command-palette [role="option"] { padding: .7rem; cursor: pointer; overflow-wrap: anywhere; }
.command-palette [aria-selected="true"] { background: #e1eafb; outline: 2px solid #4568a8; outline-offset: -2px; }
.command-palette h3 { font-size: .85rem; }
.command-palette button { margin-top: 1rem; padding: .5rem 1rem; font: inherit; }
.command-palette :focus-visible { outline: 3px solid #205ed8; outline-offset: 2px; }
